import {OBSERVATION_MODES,trackingQuality,decisionComparison,sequenceReview} from './coaching.js';
import {observationControls,sequenceStrip,comparisonView,qualityView,processView} from './coaching-view.js';
import {readReplayWindow,advanceReplay} from './replay-feed.js';
import {tacticalReading,tacticalChoices,shouldAutoAnalyze} from './tactical-reading.js';
import {spaceHeat,spaceShare} from './space-heat.js';
import {combinationOptions,recentCombination,ballIndicator} from './tactical-shapes.js';
import {clamp,clock,teamName,typeName,eventName,eventLane,isDeadBall,prepareData,appendData,observationsAt,getFrame,analyzeSnapshot,playerMetrics,loadTrend,matchFacts,localBrief,frameIndex,outsidePitch,outsideDistance,decisionReason,previousDecision} from './real-match.js';
import {pixelPlayer} from './pixel-players.js';
import {catalog} from './data-catalog.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${{play:'m8 5 11 7-11 7Z',pause:'M8 5v14M16 5v14',back:'m14 6-6 6 6 6',next:'m10 6 6 6-6 6',ball:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm0 5 5 4-2 6H9l-2-6Z',expand:'M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5',quote:'M4 4h6v8H5v6H3V9Zm11 0h6v8h-5v6h-2V9Z',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',refresh:'M4 9a8 8 0 1 1 0 7M4 3v6h6',send:'m3 3 18 9-18 9 4-9Zm4 9h14',check:'m5 12 4 4L19 6',data:'M4 4h16v16H4ZM4 9h16M4 14h16M9 4v16',down:'m6 9 6 6 6-6'}[n]||'M4 12h16'}"/></svg>`;
const button=(label,action,attrs='',cls='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const avatar=p=>`<span class="avatar ${p.team}">${pixelPlayer(p,{portrait:true})}</span>`;
const shirt=id=>data?.meta.roster.find(p=>p.id===id)?.number??id;
const playerLabel=p=>p?`${teamName(p.team)} · ${p.name}`:'Unknown player';
const lanes=[['possession','Possession'],['passes','Pass'],['turnover','Turnovers'],['duels','Duels'],['shots','Shot / Goal'],['restart','Restarts'],['discipline','Discipline'],['player','Selected player']];
let data,frame,analysis,spatial,tactical,strategies,quality,decisions,sequence,sequenceCache=new Map(),feedBusy=false,feedError='',feedRetryAt=0,rafLast=0,paint=0,stopped=false,pendingSlider=false,restoringFocus=false;
const state={screen:'match',panel:'',panelPage:0,agentView:'report',reportPage:0,time:.04,selected:'Player6',event:null,playing:false,speed:1,window:300,route:null,layers:{...OBSERVATION_MODES.decision.layers},playerOpen:false,rosterExpanded:true,rosterSort:'distance',overviewMetric:'distance',comboMode:'off',comboId:null,comboStep:2,filter:'all',eventWindow:false,onlyPlayer:false,eventPage:0,auto:new URLSearchParams(location.search).get('auto')!=='off',reports:[],activeReport:null,phase:'match',agentInput:'',models:[],model:'',modelLabel:'Local Ollama',modelProvider:'ollama',modelDefault:'',lastAutoTime:-Infinity,lastAutoWall:null,lastAutoKey:'',autoCount:0,modelState:'checking',modelBusy:false,modelTarget:null,modelError:'',references:[],sourceOpen:false,reportOpen:false,role:'analyst',focusBall:false,observationMode:'decision',comparisonId:null,reviewAnchor:null,clipEnd:null,showHistory:false};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function refresh(){frame=getFrame(data,state.time);analysis=analyzeSnapshot(frame);quality=trackingQuality(frame,{connected:!feedError,buffering:state.playing&&feedBusy&&data.frames.at(-1)[1]-state.time<.1,watermark:data.watermark});if(quality.missing){analysis.options=[];analysis.pressure=[];analysis.nearest=null;}decisions=decisionComparison(frame,analysis,data.switches);const anchor=state.reviewAnchor??Math.max(data.meta.start,Math.floor(state.time)),cacheKey=anchor+':'+state.selected;if(!sequenceCache.has(cacheKey)){sequenceCache.set(cacheKey,sequenceReview(data,anchor,state.selected));if(sequenceCache.size>8)sequenceCache.delete(sequenceCache.keys().next().value);}sequence=sequenceCache.get(cacheKey);tactical=tacticalReading(frame,analysis);strategies=tacticalChoices(frame,analysis,data.switches);spatial={combinations:combinationOptions(frame,analysis.options),history:recentCombination(data.events,state.time,frame.team)};if(!spatial.combinations.some(c=>c.id===state.comboId))state.comboId=spatial.combinations[0]?.id||null;if(!data.playerIndex.has(state.selected))state.selected=frame.holder?.id||frame.players[0]?.id;if(!analysis.options.some(o=>o.id===state.route))state.route=analysis.options[0]?.id||null;}
function selectPlayer(id){state.screen='players';if(['roster','tracking'].includes(state.panel))state.panel='';state.playerOpen=true;state.rosterExpanded=false;state.selected=id;state.route=id;state.playing=false;state.event=null;state.eventPage=0;render();}
function seek(t,event=null,keepPlayer=false){state.playing=false;state.clipEnd=null;state.time=clamp(t,data.meta.start,Math.min(data.meta.end,data.frames.at(-1)[1]));state.event=event?.id||null;if(event?.from&&!keepPlayer){state.selected=event.from;state.playerOpen=true;state.rosterExpanded=false;}state.eventPage=0;render();maybeAuto('change');}
function selectedEvent(){return receivedEvents().find(e=>e.id===state.event)||null;}
function activeCombination(){return spatial.combinations.find(c=>c.id===state.comboId);}
function trackingStatus(){const n=frame.players.filter(outsidePitch).length;return `${feedError?button('Reconnect stream','retry-feed'):''}${button(`${quality.status} · ${quality.count}/${quality.expected}`,'open-panel','data-id="quality" title="Data quality & limits"','quality-status '+(quality.status==='Tracking ready'?'':'limited'))}${n?button('Outside '+n,'open-panel','data-id="tracking"'):''}`;}
function receivedEvents(){return observationsAt(data,state.time);}
function heatReadout(){const h=spaceShare(analysis.grid);return `Arrival area · Blue ${h.home}% / Red ${h.away}% / Neutral ${h.neutral}%`;}
function feedStatus(){return feedError?'Disconnected · Retry':state.time<data.watermark-2?'Received '+clock(data.watermark):feedBusy?'Receiving':'Streamed replay';}
async function pumpFeed(initial=false){
 if(feedBusy||Date.now()<feedRetryAt||!data||data.watermark>=data.meta.end)return;
 if(!initial&&(!state.playing||data.watermark-state.time>2))return;
 feedBusy=true;feedError='';
 try{await readReplayWindow(data.frames.length?data.watermark:0,Math.min(data.meta.end,(data.frames.length?data.watermark:0)+(initial?1:8)),packet=>appendData(data,packet.frames,packet.events,packet.time));}
 catch(e){feedError=e.message;feedRetryAt=Date.now()+3000;if(initial)throw e;state.playing=false;toast(e.message);}
 finally{feedBusy=false;if(feedError&&!initial&&data.frames.length)render();}
}

function fieldReadout(){const carry=state.comparisonId==='carry'?decisions.find(r=>r.id==='carry'&&r.available):null,c=activeCombination(),o=analysis.options.find(o=>o.id===state.route),history=spatial.history;return `<div class="field-readout"><span class="ball-context">${icon('ball')} ${!frame.ball?'Ball tracking gap · Positions retained':frame.dead?'Dead ball':frame.holder?`${teamName(frame.holder.team)} ${frame.holder.number} · Estimated carrier`:'Ball in flight'}</span><span>${carry?`Carry forward ${carry.progress.toFixed(0)}m · Margin ${carry.margin.toFixed(1)}s`:state.comboMode==='potential'&&c?`${c.holder.number} → ${c.first.player.number} → ${c.third.number} · Projected · Gain ${c.progress.toFixed(0)}m · Minimum margin ${c.margin.toFixed(1)}s`:state.comboMode==='observed'?history.length?`${clock(history[0].time)}–${clock(history.at(-1).end)} · ${history.length} completed passes`:'Last  25s No pass sequence':o?`Support ${o.player.number} · ${o.distance.toFixed(0)}m · Margin ${o.margin.toFixed(1)}s`:'No carrier route'}</span></div>`;}
function combinationPanel(){const c=activeCombination();return `<div class="combination-panel">${button(strategies.phase,'open-panel','data-id="tactics" title="'+strategies.reason+'"','tactical-phase')}<select id="combo-mode" aria-label="Combination type"><option value="potential" ${state.comboMode==='potential'?'selected':''}>Two-pass projection</option><option value="observed" ${state.comboMode==='observed'?'selected':''}>Observed sequence</option><option value="off" ${state.comboMode==='off'?'selected':''}>Single pass</option></select>${state.comboMode==='potential'?`<select id="combo-choice" aria-label="Projected route">${spatial.combinations.map(x=>`<option value="${x.id}" ${x.id===state.comboId?'selected':''}>${x.holder.number} → ${x.first.player.number} → ${x.third.number}</option>`).join('')||`<option>${decisionReason(frame)}</option>`}</select>`:state.comboMode==='observed'?`<select id="sequence-choice" aria-label="Completed passes"><option value="">${spatial.history.length} completed passes</option>${spatial.history.map(e=>`<option value="${e.id}">${clock(e.time)} ${shirt(e.from)} → ${shirt(e.to)}</option>`).join('')}</select>`:'<span>Select a receiver to inspect a route</span>'}${state.comboMode==='potential'&&c?`<div class="combo-steps">${button('First pass','combo-step','data-id="1" aria-pressed="'+(state.comboStep===1)+'"',state.comboStep===1?'active':'')}${button('Full','combo-step','data-id="2" aria-pressed="'+(state.comboStep===2)+'"',state.comboStep===2?'active':'')}</div>`:''}</div>`;}

function pitch(){const f=frame,a=analysis,ball=f.ball,chosen=a.options.find(o=>o.id===state.route),combo=activeCombination(),event=selectedEvent(),eventPlayer=event?f.players.find(p=>p.id===event.from):null,eventPoint=event?(event.x!==null&&event.y!==null?{x:event.x,y:event.y}:eventPlayer):null;let layers='';
 if(state.showHistory||state.observationMode==='movement')for(const trail of sequence.trajectories){const points=trail.points.filter(p=>p.time<=state.time);if(points.length>1)layers+=`<polyline class="history-path ${trail.team}" points="${points.map(p=>p.x+','+p.y).join(' ')}"><title>${shirt(trail.id)} · Observed trail</title></polyline>`;}
 const carry=state.comparisonId==='carry'?decisions.find(r=>r.id==='carry'&&r.available):null;
 if(carry&&ball)layers+=`<path class="carry-path ${carry.margin<=0?'risk':''}" d="M${ball.x} ${ball.y}L${carry.target.x} ${carry.target.y}" marker-end="url(#run-arrow)"/><circle class="carry-target" cx="${carry.target.x}" cy="${carry.target.y}" r="1.3"/>`;

 if(state.layers.space)layers+=`<g class="control-heat" filter="url(#heat-smooth)">${a.grid.map(q=>{const heat=spaceHeat(q);if(!heat?.team)return '';return `<rect x="${q.x-1.75}" y="${q.y-1.7}" width="3.55" height="3.45" data-team="${heat.team}" fill="${heat.color}" opacity="${(heat.opacity*(state.observationMode==='decision'?.55:1)).toFixed(3)}"/>`;}).join('')}</g>`;
 if(state.layers.defense&&!f.dead)layers+=`<g class="defense-density" filter="url(#heat-smooth)">${tactical.grid.filter(q=>q.density>.8).map(q=>`<rect x="${q.x-1.75}" y="${q.y-1.7}" width="3.55" height="3.45" fill="#985000" opacity="${Math.min(.65,Math.max(0,(q.density-.8)/3)*.65).toFixed(3)}"/>`).join('')}</g>`;
 if(ball&&state.layers.corridors&&!f.dead){for(const c of tactical.corridors)layers+=`<path class="wide-corridor ${c.margin<=0?'contested':''}" d="M${ball.x} ${ball.y}L${c.target.x} ${c.target.y}" marker-end="url(#wide-arrow)"/><circle class="wide-target" cx="${c.target.x}" cy="${c.target.y}" r="2.5"><title>Wide ${c.player.number} · Margin ${c.margin.toFixed(1)}s</title></circle>`;for(const c of tactical.crossings)layers+=`<path class="cross-corridor ${c.margin<=0?'contested':''}" d="M${c.start.x} ${c.start.y}Q${(c.start.x+c.target.x)/2+f.direction*3} ${(c.start.y+c.target.y)/2} ${c.target.x} ${c.target.y}" marker-end="url(#wide-arrow)"><title>Crossing link · Margin ${c.margin.toFixed(1)}s</title></path>`;}
 if(ball&&state.layers.trail){const past=data.frames.slice(Math.max(0,f.index-15),f.index+1).filter(x=>x[3]!==null&&x[4]!==null&&x[2]===f.period);layers+=`<polyline class="ball-trail" points="${past.map(x=>`${x[3]},${x[4]}`).join(' ')}"/>`;}
 if(ball&&state.layers.pressure&&!f.dead)for(const n of a.pressure.slice(0,3)){const d=Math.hypot(ball.x-n.player.x,ball.y-n.player.y),u=d?Math.max(0,(d-2)/d):0;layers+=`<path class="pressure-line" d="M${n.player.x} ${n.player.y}L${n.player.x+(ball.x-n.player.x)*u} ${n.player.y+(ball.y-n.player.y)*u}" marker-end="url(#pressure-arrow)"/>`;}
 if(state.layers.runs&&(!f.dead||!f.ball))for(const r of a.runs)layers+=`<path class="run-line ${r.player.id===state.selected?'selected-run':''}" d="M${r.player.x} ${r.player.y}L${r.target.x} ${r.target.y}" marker-end="url(#run-arrow)"/><circle class="run-target" cx="${r.target.x}" cy="${r.target.y}" r=".55"/>`;
 if(!carry&&ball&&state.layers.passes&&state.comboMode==='potential'&&combo){layers+=`<path class="combination-area" d="M${ball.x} ${ball.y}L${combo.first.target.x} ${combo.first.target.y}L${combo.target.x} ${combo.target.y}Z"/><path class="combination-line" d="M${ball.x} ${ball.y}L${combo.first.target.x} ${combo.first.target.y}" marker-end="url(#combo-arrow)"/>`;if(state.comboStep===2)layers+=`<path class="combination-line second" d="M${combo.first.target.x} ${combo.first.target.y}L${combo.target.x} ${combo.target.y}" marker-end="url(#combo-arrow)"/><circle class="combination-target" cx="${combo.target.x}" cy="${combo.target.y}" r="1.3"/>`;}
 else if(!carry&&state.layers.passes&&state.comboMode==='observed'){for(const e of spatial.history)layers+=`<path class="sequence-line" d="M${e.x} ${e.y}L${e.endX} ${e.endY}" marker-end="url(#observed-arrow)"/><circle class="sequence-point" cx="${e.x}" cy="${e.y}" r=".7"/>`;}
 else if(!carry&&ball&&state.layers.passes&&chosen)layers+=`<path class="pass-line chosen ${chosen.margin<=0?'risky-pass':''}" d="M${ball.x} ${ball.y}L${chosen.target.x} ${chosen.target.y}" marker-end="url(#pass-arrow)"/><circle class="pass-target" cx="${chosen.target.x}" cy="${chosen.target.y}" r="1"/>`;
 if(eventPoint){layers+=`<circle class="event-mark" cx="${eventPoint.x}" cy="${eventPoint.y}" r="2.8"/>`;if(event.x!==null&&event.y!==null&&event.endX!==null&&event.endY!==null&&Math.max(event.time,event.end||0)<=state.time)layers+=`<path class="observed-path" d="M${event.x} ${event.y}L${event.endX} ${event.endY}"/>`;}
 const members=state.comboMode==='potential'&&combo?[combo.holder.id,combo.first.id,...state.comboStep===2?[combo.third.id]:[]]:[];
 const players=f.players.map(p=>`<g class="player-node ${outsidePitch(p)?'outside-pitch':''} ${state.selected===p.id?'selected':''} ${members.includes(p.id)?'combination-member':''}" transform="translate(${p.x},${p.y})" data-player="${p.id}" role="button" tabindex="0" aria-label="Select ${teamName(p.team)} player ${p.number}" aria-pressed="${state.selected===p.id}"><title>${playerLabel(p)} · ${(p.speed*3.6).toFixed(1)} km/h${outsidePitch(p)?` · Source point outside pitch ${outsideDistance(p).toFixed(1)}m, Reason unknown`:``}</title><circle class="hit" r="2.2"/><circle class="player-ring" r="2.05"/><path class="jersey ${p.team}" d="M-.7-1.5 -1.1-1.5 -2-.8 -1.5 .1 -1.05-.1 -1.05 1.5 1.05 1.5 1.05-.1 1.5 .1 2-.8 1.1-1.5 .7-1.5Q0-.7-.7-1.5Z"/><text class="jersey-number" y=".75" text-anchor="middle">${p.number}</text></g>`).join('');
 const locator=ballIndicator(ball,f.players);let ballSvg=ball?`${locator.offset?`<path class="ball-leader" d="M${ball.x} ${ball.y}L${locator.x} ${locator.y}"/><circle class="ball-exact" cx="${ball.x}" cy="${ball.y}" r=".4"/>`:''}<g class="ball-marker" transform="translate(${locator.x},${locator.y})"><title>${locator.offset?'Ball marker offset to avoid overlap; Leader endpoint is the source coordinate':'Source ball coordinate'}</title><circle class="locator" r="1.5"/><circle class="football" r=".8"/><path class="ball-patch" d="m0-.45.45.3-.15.5h-.6l-.15-.5Z"/></g>`:'';
 const vx=state.focusBall&&ball?clamp(ball.x-30,-6,51):-6,vy=state.focusBall&&ball?clamp(ball.y-21,-6,32):-6;
 return `<svg id="pitch" viewBox="${vx} ${vy} ${state.focusBall?60:117} ${state.focusBall?42:80}" aria-label="Match positions, arrival heat and passing structure"><defs><filter id="heat-smooth" x="-10%" y="-10%" width="120%" height="120%" color-interpolation-filters="sRGB"><feGaussianBlur stdDeviation="1.8"/></filter><clipPath id="pitch-clip"><rect width="105" height="68"/></clipPath>${[['wide','#008b94'],['run','#287fa1'],['pass','#754897'],['pressure','#bb4933'],['combo','#286cab'],['observed','#9b6e25']].map(([name,color])=>`<marker id="${name}-arrow" markerWidth="3" markerHeight="3" refX="2.7" refY="1.5" orient="auto"><path d="m0 0 3 1.5-3 1.5" fill="none" stroke="${color}" stroke-width=".6"/></marker>`).join('')}</defs><rect x="-4" y="-5" width="113" height="78" fill="#fff"/><g class="pitch-lines"><rect width="105" height="68"/><path d="M52.5 0v68M0 13.84h16.5v40.32H0M105 13.84H88.5v40.32H105M0 24.84h5.5v18.32H0M105 24.84h-5.5v18.32h5.5M0 30.34h-2v7.32h2M105 30.34h2v7.32h-2"/><circle cx="52.5" cy="34" r="9.15"/><path d="M16.5 26.7a9.15 9.15 0 0 1 0 14.6M88.5 26.7a9.15 9.15 0 0 0 0 14.6"/></g><g class="field-overlays" clip-path="url(#pitch-clip)">${layers}</g><g class="pitch-dots"><circle cx="52.5" cy="34" r=".3"/><circle cx="11" cy="34" r=".3"/><circle cx="94" cy="34" r=".3"/></g>${players}${ballSvg}</svg>`;}
function bounds(){const size=state.window===0?Math.max(1,data.watermark):state.window;let start=clamp(state.time-size/2,0,Math.max(0,data.meta.end-size));return {start,end:Math.min(data.meta.end,start+size),size};}
function timeline(){const {start,end,size}=bounds(),known=receivedEvents(),visible=known.filter(e=>e.time>=start&&e.time<=end),selected=state.selected;return `<section class="timeline-panel"><div class="section-head"><h2>Match timeline</h2><label class="compact-label">Window<select id="time-window">${[[120,'2  min'],[300,'5  min'],[900,'15  min'],[0,'Received']].map(([v,n])=>`<option value="${v}" ${state.window===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="transport"><div>${button(icon('back'),'back','aria-label="Back 5 s"')}${button(icon(state.playing?'pause':'play'),'play',`aria-label="${state.playing?'Pause replay':'Play replay'}"`,'primary')}${button(icon('next'),'next','aria-label="Forward 5 s"')}<time id="transport-time">${clock(state.time)}</time></div><label>Speed<select id="speed">${[1,2,4,8].map(v=>`<option value="${v}" ${state.speed===v?'selected':''}>${v}×</option>`).join('')}</select></label></div><input type="range" id="time-seek" min="0" max="${Math.max(data.meta.start,data.frames.at(-1)[1])}" step=".2" value="${state.time}" aria-label="Received replay time"><div class="all-match-events" aria-hidden="true">${known.filter(e=>e.type==='CARD'||['SHOT','BALL OUT'].includes(e.type)&&e.subtype.split('-').includes('GOAL')).map(e=>`<i style="left:${e.time/Math.max(1,data.watermark)*100}%" class="${e.type==='CARD'?'card-mark':'goal-mark'}"></i>`).join('')}</div><div class="timeline-scale"><span>00:00</span><span>${known.length.toLocaleString()} completed events</span><span>Received ${clock(data.watermark)}</span></div><div class="lane-scale"><span></span><div>${[0,.25,.5,.75,1].map(q=>`<time style="left:${q*100}%">${clock(start+size*q)}</time>`).join('')}</div></div><div class="event-lanes">${lanes.map(([key,title])=>{const list=key==='possession'?data.switches.filter(e=>e.time>=start&&Math.max(e.time,e.end||0)<=state.time&&e.time<=end):key==='player'?visible.filter(e=>e.from===selected||e.to===selected):visible.filter(e=>eventLane(e)===key);return `<div class="lane-row"><span>${title}<small>${list.length}</small></span><div class="lane-track" data-lane="${key}"><i class="playhead" style="left:${(state.time-start)/size*100}%"></i>${list.map(e=>`<button class="event-dot ${key} ${e.team} ${e.subtype==='YELLOW'?'yellow':''} ${e.subtype==='RED'?'red':''} ${state.event===(e.sourceId||e.id)?'active':''}" style="left:${(e.time-start)/size*100}%" data-action="event" data-id="${e.sourceId||e.id}" aria-label="${clock(e.time)} ${e.type==='SWITCH'?'Possession to'+teamName(e.team):teamName(e.team)+' '+eventName(e)}" title="${clock(e.time)} · ${e.type==='SWITCH'?'Possession to'+teamName(e.team):teamName(e.team)+' '+eventName(e)}"></button>`).join('')}</div></div>`;}).join('')}</div></section>`;}
function eventDetail(){const e=selectedEvent()||frame.last;if(!e)return '<p class="empty">No events yet</p>';const p=data.meta.roster.find(p=>p.id===e.from);return `<div class="event-detail"><div class="section-head"><h3>${eventName(e)}</h3><time>${clock(e.time)}</time></div><p>${playerLabel(p)}${e.to?' → '+(data.meta.roster.find(p=>p.id===e.to)?.name||e.to):''}</p><div class="event-actions">${button('Review previous 5 s','lead-in',`data-time="${e.time}"`)}${button('Cite','quote-event',`data-id="${e.id}"`)}</div></div>`;}
function situationColumn(){const a=analysis,p=frame.holder,route=a.options.find(o=>o.id===state.route),n=a.nearest,defender=frame.players.find(p=>p.id===route?.interceptor);return `<section class="insight-column situation-column"><div class="column-head"><h2>Tactical state</h2><span>${clock(frame.time)}</span></div><section class="column-section"><div class="identity">${p?avatar(p):`<span class="avatar ball-avatar">${icon('ball')}</span>`}<div><h3>${frame.dead?'Dead ball · Awaiting restart':p?playerLabel(p):frame.ball?'Ball in flight':'Ball coordinates missing'}</h3><p>${p?'Estimated carrier':frame.dead?'Restart phase':'Carrier unconfirmed'}</p></div></div><dl class="pressure-facts"><div><dt>Pressers <small>Estimate ≤2.7s</small></dt><dd>${frame.dead?'—':a.pressure.length}</dd></div><div><dt>Nearest opponent</dt><dd>${n?`${n.player.number} · ${n.distance.toFixed(1)} m`:'—'}</dd></div><div><dt>Time to ball <small>Estimate</small></dt><dd>${n&&!frame.dead?n.time.toFixed(1)+' s':'—'}</dd></div></dl></section><section class="column-section"><div class="section-head"><h3>Passing options</h3><span>Estimate · Single pass</span></div><div class="option-table-head"><span>Receiver</span><span>Distance</span><span>Gain</span><span title="Defender arrival minus ball arrival; Positive means ball arrives first">Margin</span></div>${a.options.slice(0,4).map(o=>`<button class="option-row ${o.id===state.route?'active':''}" data-action="route" data-id="${o.id}" aria-pressed="${o.id===state.route}" aria-label="View${o.player.name}Pass route, Distance${o.distance.toFixed(0)}m, Forward gain${o.progress.toFixed(0)}m, Interception margin${o.margin.toFixed(1)}s"><span class="option-person">${avatar(o.player)}<span><strong>${o.player.name}</strong><small>${o.offside?'Offside risk':o.margin>0?'Ball first':'Opponent first'}</small></span></span><span>${o.distance.toFixed(0)}<small>m</small></span><span>${o.progress>0?'+':''}${o.progress.toFixed(0)}<small>m</small></span><span class="margin-value ${o.margin<0?'risk':''}">${o.margin>0?'+':''}${o.margin.toFixed(1)}<small>s</small></span></button>`).join('')||'<p class="empty">No available carrier route</p>'}${defender?`<div class="route-context"><span>Route defender</span>${button(`${teamName(defender.team)} ${defender.number}`,'inspect-defender',`data-id="${defender.id}"`)}</div>`:''}</section><section class="column-section"><div class="section-head"><h3>${frame.ball?'Off-ball runs':'Movement'}</h3><span>Projection 2s</span></div><div class="run-table-head"><span>Movement / Support</span><span>Speed</span><span>Arrival advantage</span></div>${a.runs.slice(0,4).map(r=>`<button class="run-row ${state.selected===r.player.id?'active':''}" data-player="${r.player.id}" aria-pressed="${state.selected===r.player.id}"><span class="option-person">${avatar(r.player)}<span><strong>${r.player.number} · ${r.label}</strong><small>${r.advantage>0?'Team first':'Opponent first'}</small></span></span><span>${(r.player.speed*3.6).toFixed(1)}<small>km/h</small></span><span class="margin-value ${r.advantage<0?'risk':''}">${r.advantage>0?'+':''}${r.advantage.toFixed(1)}<small>s</small></span></button>`).join('')||'<p class="empty">No clear off-ball movement</p>'}</section><section class="column-section"><div class="section-head"><h3>Event review</h3><span>${selectedEvent()?'Selected event':'Latest event'}</span></div>${eventDetail()}</section></section>`;}
function valueButton(value,label,filter,title=''){return `<button class="evidence-metric" data-action="metric" data-id="${filter}" title="${title||'Filter events for this player'}"><strong>${value}</strong><span>${label}</span></button>`;}
function playerProjection(p){const live=frame.players.find(v=>v.id===p.id);if(!live)return '<p class="empty">No current tracking</p>';if(outsidePitch(live))return `<p class="empty">Source point outside pitch ${outsideDistance(live).toFixed(1)}m · Reason unknown. ${button('Position evidence','open-panel','data-id="tracking"')}</p>`;const others=frame.players.filter(v=>v.team!==p.team),nearest=Math.min(...others.map(v=>Math.hypot(v.x-live.x,v.y-live.y))),option=analysis.options.find(o=>o.id===p.id);return `<dl class="player-projection"><div><dt>Current speed</dt><dd>${(live.speed*3.6).toFixed(1)} km/h</dd></div><div><dt>Nearest opponent</dt><dd>${Number.isFinite(nearest)?nearest.toFixed(1)+' m':'—'}</dd></div><div><dt>2s Movement projection</dt><dd>${(Math.hypot(live.vx,live.vy)*2).toFixed(1)} m</dd></div><div><dt>Receiving margin · Estimate</dt><dd>${option?option.margin.toFixed(1)+' s':'—'}</dd></div></dl>`;}
function playerEventTracks(){const start=Math.max(0,state.time-600),width=Math.max(1,state.time-start),events=data.events.filter(e=>e.time>=start&&Math.max(e.time,e.end||0)<=state.time&&(e.from===state.selected||e.to===state.selected));return `<div class="player-event-tracks"><div class="player-track-scale"><time>${clock(start)}</time><span>Player events · Last 10′</span><time>${clock(state.time)}</time></div>${[['Touches',e=>['PASS','RECOVERY','SHOT'].includes(e.type),'touch'],['Losses',e=>e.type==='BALL LOST','loss'],['Duels',e=>e.type==='CHALLENGE','duel']].map(([label,accept,key])=>`<div class="player-track"><span>${label}</span><div>${events.filter(accept).map(e=>button('','player-event',`data-id="${e.id}" title="${clock(e.time)} ${eventName(e)}" aria-label="${clock(e.time)} ${eventName(e)}" style="left:${Math.min(98,(e.time-start)/width*100)}%"`,'track-mark '+key)).join('')}</div></div>`).join('')}</div>`;}
function eventRow(e){return `<button class="event-row ${state.event===e.id?'active':''}" data-action="player-event" data-id="${e.id}"><time>${clock(e.time)}</time><i class="event-key ${eventLane(e)} ${e.team}"></i><span><strong>${eventName(e)}</strong><small>${teamName(e.team)} ${data.meta.roster.find(p=>p.id===e.from)?.name||'No player specified'}</small></span>${icon('arrow')}</button>`;}
function reportView(report){return `<article class="agent-report"><div class="report-head"><strong>${esc(report.title)}</strong><time>${clock(report.time)}</time></div><p>${esc(report.summary)}</p><p>${esc(report.advice)}</p><div class="report-evidence">${report.evidence.slice(0,4).map(id=>{const e=data.events.find(e=>e.id===id);return e?button(`${clock(e.time)} ${eventName(e).split(' · ')[0]}`,'event',`data-id="${id}"`):'';}).join('')}</div><small>${esc(report.limits)}</small>${report.phase==='post'&&report.time<data.meta.end-.25?button('Available at full time','finish-report','disabled'):''}</article>`;}
function squadEvidence(){return frame.players.map(p=>({p,m:playerMetrics(data,p.id,state.time)}));}
function participationChart(rows){const key=state.overviewMetric,label=key==='high'?'High-speed distance':'Distance',valid=rows.filter(r=>r.m.active>0),maxX=Math.max(5,Math.ceil(Math.max(0,...valid.map(r=>r.m.touches))/5)*5),maxY=Math.max(100,Math.ceil(Math.max(0,...valid.map(r=>r.m[key]))/100)*100),x=v=>48+v/maxX*408,y=v=>219-v/maxY*177,selected=rows.find(r=>r.p.id===state.selected),readout=r=>`${teamName(r.p.team)} ${r.p.number} · Touches ${r.m.touches}  times · ${label} ${Math.round(r.m[key])} m · Losses ${r.m.lost}  times`;return `<div class="participation-chart"><div class="chart-heading"><h3>Involvement & movement</h3><select id="overview-metric" aria-label="Chart movement metric"><option value="distance" ${key==='distance'?'selected':''}>Total distance</option><option value="high" ${key==='high'?'selected':''}>High-speed distance</option></select></div><div class="participation-legend"><span><i class="team-dot home"></i>Home</span><span><i class="team-dot away"></i>Away</span><span>One point per tracked player</span></div><svg class="participation-plot" viewBox="0 0 480 258" role="group" aria-label="Last 5 min touches and ${label}: player distribution, Select a player for detail"><text class="axis-title" x="48" y="19">${label} (m)</text>${[0,.25,.5,.75,1].map(t=>`<path class="chart-grid" d="M48 ${y(t*maxY)}H456"/><text class="axis-tick" x="39" y="${y(t*maxY)+3}" text-anchor="end">${Math.round(t*maxY)}</text>`).join('')}${[0,.2,.4,.6,.8,1].map(t=>`<text class="axis-tick" x="${x(t*maxX)}" y="235" text-anchor="middle">${Math.round(t*maxX)}</text>`).join('')}<text class="axis-title" x="456" y="253" text-anchor="end">Touch events</text>${valid.sort((a,b)=>Number(a.p.id===state.selected)-Number(b.p.id===state.selected)).map(r=>`<g class="participation-point ${r.p.team} ${state.playerOpen&&r.p.id===state.selected?'active':''}" data-player="${r.p.id}" data-chart-readout="${readout(r)}" transform="translate(${x(r.m.touches)},${y(r.m[key])})" role="button" tabindex="0" aria-label="${readout(r)}, View player" aria-pressed="${state.playerOpen&&r.p.id===state.selected}"><title>${readout(r)}${r.m.active<180?' · Less than 3 min of tracking':''}</title><circle class="chart-hit" r="10"/><circle class="chart-dot" r="4.5"/>${state.playerOpen&&r.p.id===state.selected?`<circle class="chart-focus" r="8"/><text class="point-label" x="${r.m.touches>maxX*.9?-11:11}" y="3" text-anchor="${r.m.touches>maxX*.9?'end':'start'}">${r.p.number}</text>`:''}</g>`).join('')}</svg><div class="chart-readout" aria-live="polite">${state.playerOpen&&selected?readout(selected):valid.length?'Hover for values · Select a player to link review':'No valid tracking window yet'}</div><div class="team-averages">${['home','away'].map(team=>{const group=valid.filter(r=>r.p.team===team),n=group.length;return `<div><span><i class="team-dot ${team}"></i>${teamName(team)} · Per player</span><strong>${n?(group.reduce((v,r)=>v+r.m.touches,0)/n).toFixed(1):'—'}<small> touches</small></strong><strong>${n?Math.round(group.reduce((v,r)=>v+r.m[key],0)/n):'—'}<small> m</small></strong></div>`;}).join('')}</div></div>`;}
function squadRoster(rows){const key=state.overviewMetric,label=key==='high'?'High speed m':'Distance m',expanded=!state.playerOpen||state.rosterExpanded;return `<section class="squad-roster"><div class="roster-heading"><h3>Players</h3><span>${rows.length}  players · Last 5′</span>${state.playerOpen?button(expanded?'Collapse roster':'Switch player','roster-toggle',`aria-expanded="${expanded}"`):''}</div>${expanded?`<div class="team-rosters">${['home','away'].map(team=>{const members=rows.filter(r=>r.p.team===team).sort((a,b)=>(b.m[state.rosterSort]-a.m[state.rosterSort])||a.p.number-b.p.number),absent=data.meta.roster.filter(p=>p.team===team&&!rows.some(r=>r.p.id===p.id));return `<section class="team-roster ${team}"><h4><i class="team-dot ${team}"></i>${teamName(team)}<span>${members.length}  players</span></h4><div class="roster-table-head"><span>Player</span>${[['touches','Involv.'],['lost','Lost'],[key,'m']].map(([k,n])=>button(n,'roster-sort',`data-id="${k}" title="Sort by ${n}, descending" aria-pressed="${state.rosterSort===k}"`)).join('')}</div>${members.map(({p,m})=>`<button class="roster-data-row ${state.playerOpen&&p.id===state.selected?'active':''}" data-player="${p.id}" aria-label="View ${teamName(team)} player ${p.number}, Touches${m.touches} times, Losses${m.lost} times, ${key==='high'?'High-speed distance':'Distance'}${Math.round(m[key])}m" aria-pressed="${state.playerOpen&&p.id===state.selected}"><span class="roster-person">${avatar(p)}<strong>${p.number}</strong></span><span>${m.touches}</span><span class="${m.lost?'has-loss':''}">${m.lost}</span><span>${Math.round(m[key])}</span></button>`).join('')}${absent.length?button('Untracked · '+absent.length,'roster-full','','untracked-button'):''}</section>`;}).join('')}</div>`:''}</section>`;}
function squadOverview(){const rows=squadEvidence();return `<section class="squad-overview" aria-label="Player overview"><div class="overview-heading"><h2>Player overview</h2><time>${clock(Math.max(0,state.time-300))}–${clock(state.time)}</time></div>${participationChart(rows)}${squadRoster(rows)}</section>`;}
function playerWorkspace(){return `<div class="player-detail ${state.playerOpen?'show-player':''}">${squadOverview()}${state.playerOpen?`<div class="player-inspector"><div class="inspector-nav">${button(icon('back')+'Back to roster','player-overview')}<span>${playerLabel(data.meta.roster.find(p=>p.id===state.selected))}</span><div>${button(icon('back'),'adjacent-player','data-id="-1" aria-label="Previous player"')}${button(icon('next'),'adjacent-player','data-id="1" aria-label="Next player"')}</div></div>${playerColumn()}</div>`:''}</div>`;}

function matchOverview(){const facts=matchFacts(data,state.time),report=state.reports.filter(r=>r.phase!=='match').at(-1);return `<section class="match-overview"><div class="column-head"><h2>Match totals</h2><span>As of ${clock(state.time)}</span></div><section class="column-section"><table class="match-facts"><thead><tr><th>Match events</th><th class="home-text">Home</th><th class="away-text">Away</th></tr></thead><tbody>${[['shots','Shot','shots'],['onTarget','On target','shots'],['passes','Completed passes','passes'],['lost','Possession lost','turnover'],['foulsReceived','Fouled','discipline'],['corners','Corner','restart'],['yellow','Yellow card','yellow'],['red','Red card','red']].map(([k,n,filter])=>`<tr><th>${button(n,'match-filter',`data-id="${filter}"`)}</th><td>${facts.home[k]}</td><td>${facts.away[k]}</td></tr>`).join('')}</tbody></table></section><details class="match-review-agent"><summary>Match report</summary><div class="agent-lifecycle">${button('Pre-match check','brief-pre')}${button('Post-match review','brief-post')}</div>${report?reportView(report):''}</details></section>`;}
function filterMatch(e){const f=state.filter;if(f==='all')return true;if(f==='player')return e.from===state.selected||e.to===state.selected;if(f==='lost')return e.type==='BALL LOST';if(f==='ground')return e.type==='CHALLENGE'&&/GROUND|TACKLE|DRIBBLE/.test(e.subtype);if(f==='aerial')return e.type==='CHALLENGE'&&e.subtype.includes('AERIAL');if(f==='fouled')return e.type==='FAULT RECEIVED';if(f==='yellow'||f==='red')return e.type==='CARD'&&e.subtype===f.toUpperCase();return eventLane(e)===f;}
function eventLedger(){let list=receivedEvents().filter(filterMatch);if(state.eventWindow)list=list.filter(e=>e.time>state.time-300&&Math.max(e.time,e.end||0)<=state.time);if(state.onlyPlayer)list=list.filter(e=>e.from===state.selected||e.to===state.selected);const found=state.event?list.findIndex(e=>e.id===state.event):list.findIndex(e=>e.time>=state.time),current=found<0?list.length-1:found,start=clamp(Math.max(0,current-2)+state.eventPage*10,0,Math.max(0,list.length-10)),items=list.slice(start,start+10);return `<section class="event-ledger" id="event-ledger"><div class="section-head ledger-head"><div><h2>Events <span class="record-count">${list.length} events</span></h2></div><div class="ledger-controls"><label>Events<select id="event-filter">${[['all','All types'],['lost','Possession lost'],['ground','Ground duel'],['aerial','Aerial duel'],['fouled','Fouled'],['yellow','Yellow card'],['red','Red card'],...lanes.filter(x=>x[0]!=='possession')].map(([v,n])=>`<option value="${v}" ${state.filter===v?'selected':''}>${n}</option>`).join('')}</select></label><label><input id="only-player" type="checkbox" ${state.onlyPlayer?'checked':''}>Selected player only</label><label><input id="event-window" type="checkbox" ${state.eventWindow?'checked':''}>Last 5 min</label>${button('Previous','events-prev',start===0?'disabled':'')}${button('Next','events-next',start+10>=list.length?'disabled':'')}</div></div><div class="ledger-table"><table><thead><tr><th>Replay time</th><th>Team / Player</th><th>Events</th><th>Receiver / Outcome</th><th>Action</th></tr></thead><tbody>${items.map(e=>`<tr class="${state.event===e.id?'active':''}"><td>${clock(e.time)}</td><td><span class="team-dot ${e.team}"></span>${teamName(e.team)} · ${data.meta.roster.find(p=>p.id===e.from)?.name||'Unspecified'}</td><td>${typeName[e.type]}</td><td>${e.to?(data.meta.roster.find(p=>p.id===e.to)?.name||e.to):eventName(e)}</td><td>${button('Seek','event',`data-id="${e.id}"`)}${button('Cite','quote-event',`data-id="${e.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5">No events match this filter</td></tr>'}</tbody></table></div></section>`;}
function coverage(){return `<section class="coverage-section" id="data-coverage"><details ${state.sourceOpen?'open':''}><summary><span>${icon('data')}Data & definitions</span><span>Source observations / Computed / Projection / Unavailable</span></summary><p>${esc(data.meta.notice)}</p><div class="source-links"><a href="/data/synthetic/manifest.json" target="_blank" rel="noreferrer">Synthetic source manifest ↗</a><a href="/coach-validation.html" target="_blank" rel="noreferrer">Scenario validation ↗</a></div><div class="metric-definitions"><h3>Metric definitions</h3><dl><div><dt>Pressure / Receiving space</dt><dd>Compare earliest arrival at each pitch sample. Blue always means home arrives first, Red always means away arrives first; Neutral if difference is at most 0.25s in the blank areas. Area share is not possession, or attacking-half occupancy. Intensity derives continuously from arrival difference and fastest arrival, with spatial smoothing; Light areas mean small differences or distant players. Not a historical running heatmap, or a calibrated control probability. </dd></div><div><dt>Combination type</dt><dd>Dashed lines show two-pass candidates from current positions, Includes first-pass travel, 0.4s handling and second-pass travel time, Defenders use the current snapshot. Solid lines show the last 25s of completed passes in one possession chain. This does not establish a planned tactic; Team playbook/and calls are not available. </dd></div><div><dt>Ball marker</dt><dd>Shirts are placed at tracked coordinates. Only the ball icon moves when it overlaps a player, The leader endpoint marks the source ball position. No text labels on the pitch. </dd></div><div><dt>Pass margin</dt><dd>Minimum defender arrival minus ball arrival along the route; Positive means ball first. Gain is displacement along the attacking direction, Not expected value. Shared reaction 0.6s, Movement 6.5m/s, Ground ball 15m/s; No individual ability or calibrated success probability. </dd></div><div><dt>Off-ball movement</dt><dd>Current coordinates and past 1s velocity projected for 2s. Arrival advantage compares each team fastest arrival at the target, Not a prescribed run. Active routes are paused at dead balls. </dd></div><div><dt>Movement load</dt><dd>High speed ≥5.5m/s, Sprint ≥7m/s, Strong acceleration ≥2.5m/s². The final column is an incomplete 1 minute interval. Shared thresholds are not fitness or fatigue diagnoses. </dd></div><div><dt>Event definitions</dt><dd>Touch events include passes/receives, Regains, losses and shots, Not every physical touch. Possession changes derive from adjacent possession events. Fouls received use discipline events, Duel fouls are shown separately. </dd></div><div><dt>Player identity</dt><dd>Names and shirt numbers identify fictional players in a seeded simulation. Carrier estimated by proximity to the ball; No official bench or individual ability data. </dd></div></dl></div><div class="coverage-table"><table><thead><tr><th>Domain</th><th>Fields & metrics</th><th>Availability</th><th>Source & limits</th></tr></thead><tbody>${catalog.map(([group,name,status,note])=>`<tr><th>${group}</th><td>${name}</td><td><span class="tag ${status}">${{observed:'Observed',derived:'Computed locally',predicted:'Model estimate',missing:'Unavailable'}[status]}</span></td><td>${note}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function assignFocusKeys(){
 const counts=new Map();
 for(const el of document.querySelectorAll('#app button,#app input,#app select,#app textarea,#app summary,#app [data-player]')){
  const scope=el.closest('[data-lane],.insight-column,.timeline-panel,.event-ledger,.header-actions,.selection-strip,.squad-overview,.combination-panel,#pitch');
  const context=scope?.dataset.lane||scope?.id||scope?.classList[0]||'app';
  const identity=el.id?'id:'+el.id:el.dataset.player?'player:'+el.dataset.player:el.dataset.action?'action:'+el.dataset.action+':'+(el.dataset.id||el.dataset.time||el.dataset.index||''):'control:'+el.tagName+':'+el.textContent.trim();
  const base=context+'/'+identity,occurrence=counts.get(base)||0;counts.set(base,occurrence+1);el.dataset.focusKey=base+'/'+occurrence;
 }
}
function saveFocus(){const el=document.activeElement;if(!el?.dataset.focusKey)return null;return {key:el.dataset.focusKey,start:el.tagName==='TEXTAREA'?el.selectionStart:null,end:el.tagName==='TEXTAREA'?el.selectionEnd:null};}
function restoreFocus(saved){if(!saved)return;const el=[...document.querySelectorAll('[data-focus-key]')].find(x=>x.dataset.focusKey===saved.key);if(!el)return;restoringFocus=true;try{el.focus({preventScroll:true});if(saved.start!==null)el.setSelectionRange(saved.start,saved.end);}finally{restoringFocus=false;}}
function syncPlaybackControls(){const label=$('#play-state');if(label)label.textContent=state.playing?'Playing':'Paused';const b=document.querySelector('[data-action=play]');if(b){b.innerHTML=icon(state.playing?'pause':'play');b.setAttribute('aria-label',state.playing?'Pause replay':'Play replay');}document.querySelector('.play-indicator')?.classList.toggle('playing',state.playing);}
function render(){if(!data)return;refresh();const focus=saveFocus(),open=[...document.querySelectorAll('details[open]')].map(x=>x.className),scrolls=[...document.querySelectorAll('.player-detail')].map(x=>x.scrollTop);
 $('#app').innerHTML=`<header class="app-header" ${state.panel?'inert':''}><a class="brand" href="/">${icon('ball')}<strong>NEXT TOUCH</strong><span>Match intelligence</span></a><div class="header-source"><span class="source-dot"></span>Synthetic · Seed 7<span class="local-pill" id="feed-state">${feedStatus()}</span></div><div class="header-actions">${button(icon('data')+'Events','open-panel','data-id="events"')}${button('Definitions','source')}${button(icon('expand')+'Full screen','fullscreen')}</div></header><div class="match-heading" ${state.panel?'inert':''}><div><h1>Match review</h1></div><div class="scoreboard"><span><i class="team-dot home"></i>Home</span><strong id="score">${frame.score.home}<small>:</small>${frame.score.away}</strong><span>Away<i class="team-dot away"></i></span><time id="match-clock">${clock(state.time)}</time><span id="period-label">${frame.period===1?'First half':'Second half'}</span></div><label class="role-select">Role<select id="role"><option value="analyst" ${state.role==='analyst'?'selected':''}>Analyst</option><option value="coach" ${state.role==='coach'?'selected':''}>Coach</option><option value="director" ${state.role==='director'?'selected':''}>Producer</option></select></label></div><main class="desk-main" ${state.panel?'inert':''}><nav class="mobile-desk-nav" aria-label="Workspace">${button('Match','screen','data-id="match" aria-pressed="'+(state.screen==='match')+'"')}${button('Player','screen','data-id="players" aria-pressed="'+(state.screen==='players')+'"')}${button('Events','open-panel','data-id="events"')}</nav><div class="workspace screen-${state.screen}"><section class="field-column"><div class="match-stage"><div class="field-shell"><div class="field-toolbar"><div><span class="play-indicator ${state.playing?'playing':''}"></span><strong id="play-state">${state.playing?'Playing':'Paused'}</strong><span>5 Hz stream</span><span id="tracking-status">${trackingStatus()}</span></div>${button(icon('quote'),'reference','aria-label="Cite this moment"')}${button(icon('ball')+(state.focusBall?'Full pitch':'Follow ball'),'focus-ball',`aria-pressed="${state.focusBall}"`)}</div><div id="field-mount">${pitch()}</div><div id="field-readout">${fieldReadout()}</div><div class="field-legend"><span><i class="football-key"></i>Ball</span><span class="line-key pressure">Press</span><span class="line-key run">Off ball 2s</span><span class="line-key pass">Dashed: projected / Solid: observed</span><span class="heat-key" id="heat-share" title="Area with arrival difference above 0.25s across the pitch; Not possession"><i></i>${heatReadout()}</span><span class="density-key">Amber · ${tactical.defendingTeam?teamName(tactical.defendingTeam):'Defence'} density</span><span class="corridor-key">Teal · wide candidates</span><span>${frame.homeDirection===1?'Home attacks →':'← Home attacks'}</span></div>${observationControls(state.observationMode,state.layers)}<div id="combination-mount">${combinationPanel()}</div></div><div id="match-review-mount">${matchReview()}</div></div><div id="sequence-mount">${sequenceStrip(sequence,state.reviewAnchor!==null)}</div><div id="timeline-mount">${timeline()}</div></section><aside id="insights" class="insights" aria-label="Player analysis">${playerWorkspace()}</aside><aside id="agent-dock" aria-label="Agent Assistant">${agentColumn()}</aside></div></main>${utilityPanel()}`;

 [...document.querySelectorAll('.player-detail')].forEach((x,i)=>x.scrollTop=scrolls[i]||0);for(const e of document.querySelectorAll('details'))if(open.includes(e.className)&&e.className)e.open=true;assignFocusKeys();restoreFocus(focus);const panel=document.querySelector('.utility-panel');if(panel&&!panel.contains(document.activeElement))panel.querySelector('button')?.focus({preventScroll:true});}
function updateScene(){refresh();$('#field-mount').innerHTML=pitch();if($('#sequence-mount'))$('#sequence-mount').innerHTML=sequenceStrip(sequence,state.reviewAnchor!==null);if($('#tracking-status'))$('#tracking-status').innerHTML=trackingStatus();$('#field-readout').innerHTML=fieldReadout();if($('.density-key'))$('.density-key').textContent='Amber · '+(tactical.defendingTeam?teamName(tactical.defendingTeam):'Defence')+'density';if($('#agent-dock')&&!$('#dock-question')?.matches(':focus'))$('#agent-dock').innerHTML=agentColumn();$('#match-clock').textContent=clock(state.time);$('#score').innerHTML=`${frame.score.home}<small>:</small>${frame.score.away}`;$('#period-label').textContent=frame.period===1?'First half':'Second half';$('#transport-time').textContent=clock(state.time);$('#time-seek').max=data.frames.at(-1)[1];$('#heat-share').innerHTML='<i></i>'+heatReadout();$('#feed-state').textContent=feedStatus();$('#time-seek').value=state.time;$('#play-state').textContent=state.playing?'Playing':'Paused';}
function addBrief(phase='match',time=state.time,trigger='manual',question=''){state.reportPage=0;const brief=localBrief(data,time,state.selected,phase);if(phase==='match'){const p=data.meta.roster.find(p=>p.id===state.selected),m=playerMetrics(data,state.selected,time);brief.title=p.name+' · Performance review';brief.summary=`${p.name} · Last 5 min: completed passes ${m.passes}  times, Possession lost ${m.lost}  times, Ground duel ${m.won}/${m.duels}. `;brief.advice=`distance in same period ${Math.round(m.distance)} m, High-speed distance ${Math.round(m.high)} m, Sprint ${Math.round(m.sprints)}  times. ${m.active<180?'Less than 3 min of valid tracking. ':'Use the event lanes to locate losses and duels. '}Load changes require role context, They cannot diagnose declining fitness alone. `;brief.evidence=m.events.slice(-4).map(e=>e.id);}if(question){brief.title=(data.meta.roster.find(p=>p.id===state.selected)?.name||'Player')+' · Cited question';if(/fitness|status|substitution|fatigue/i.test(question)){const m=playerMetrics(data,state.selected,time);brief.advice=`This player in the last 5 min distance ${Math.round(m.distance)} m, High-speed distance ${Math.round(m.high)} m, Possession lost ${m.lost}  times, Ground duel ${m.won}/${m.duels}. Review losses and duels first, then consider the tactical role; No injury data, official bench or individual baseline, No direct fatigue or substitution conclusion. `;brief.evidence=m.events.filter(e=>['BALL LOST','CHALLENGE'].includes(e.type)).slice(-4).map(e=>e.id);}else brief.advice='Based on the cited state: '+brief.advice;brief.summary=`Your question: ${question}\n${brief.summary}`;brief.limits+=' Rule-based answers cover the current state, load and event evidence. ';}
 if(state.role==='director')brief.advice='Producer view: Show defender arrival around the ball first, then off-ball support. '+brief.advice;
 if(state.role==='coach')brief.advice='Coach view: Check support and protection before the next restart. '+brief.advice;
 if(trigger==='manual'||trigger==='question')state.reportOpen=true;
 const report={...brief,provider:'rules',id:crypto.randomUUID(),trigger,selected:state.selected};state.reports.push(report);if(state.reports.length>60)state.reports.shift();state.activeReport=report.id;return report;}
function addReference(time=state.time,event=null){const item={id:crypto.randomUUID(),time,selected:event?.from||state.selected,event:event?.id||null,label:event?eventName(event):playerLabel(data.meta.roster.find(p=>p.id===state.selected))};state.references.push(item);return item;}
async function checkModel(){state.modelState='checking';state.modelError='';try{const r=await fetch('/api/match-agent/status');if(!r.ok)throw Error('Model service unavailable; Evidence rules remain available. ');const value=await r.json();state.models=value.models||[];state.modelLabel=value.label||'Model';state.modelProvider=value.provider;state.modelState=state.models.length?'ready':'offline';if(!state.models.includes(state.model))state.model=value.defaultModel||'';state.modelDefault=value.defaultModel||'';if(!state.models.length&&value.message)state.modelError=value.message;}catch(e){state.modelState='offline';state.modelError=e.message;}render();maybeAuto('entry');}
async function generateReport(phase='match',time=state.time,trigger='manual',question=''){
 if(state.modelBusy){if(trigger!=='dead-ball')toast('Analysis is running');return;}
 const report=addBrief(phase,phase==='pre'?0:time,trigger,question),model=state.model,label=state.modelLabel;
 if(!model||phase==='post'&&time<data.meta.end-.25){render();return;}
 const prompt=question||(phase==='pre'?'Using available pre-match evidence, list the checks a coach should make. ':phase==='post'?'Summarize the match and selected player, Give evidence-based review priorities. ':'Evaluate the selected player at this time, Consider available passes, combinations and off-ball movement. ');
 state.modelBusy=true;state.modelTarget=report.selected;state.modelError='';report.pending=true;render();
 try{const r=await fetch('/api/match-agent/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,question:prompt,time:report.time,player:report.selected,phase})});const result=await r.json();if(!r.ok)throw Error(result.error?.message||'The model returned no answer');
  report.title=label+' · '+(phase==='pre'?'Pre-match check':phase==='post'?'Post-match review':['entry','change','dead-ball'].includes(trigger)?'Proactive feedback':question?'Cited question':'Player review');
  report.summary=`Cite ${clock(report.time)} · ${playerLabel(data.meta.roster.find(p=>p.id===report.selected))}${question?' · '+question:''}`;
  report.advice=result.answer;report.provider=result.provider;report.model=result.model;report.durationMs=result.durationMs;report.usage=result.usage;report.reviewWarnings=result.reviewWarnings||[];
  report.limits=`Agent · ${(result.durationMs/1000).toFixed(1)}s. Generated from cited-time evidence; Advice has not been reviewed by a person. ${result.truncated?'Answer reached the length limit. ':''}${report.reviewWarnings.join(' ')}`;
 }catch(e){report.error=e.message;state.modelError=e.message;if(/Quota/.test(e.message))state.auto=false;report.limits='Model request failed: '+e.message+' Evidence-based observations remain below. ';toast(label+'Incomplete, Rule-based observations retained. ');}
 finally{report.pending=false;state.modelBusy=false;render();}
}
async function ask(){const q=state.agentInput.trim();if(!q){toast('Enter a question about this moment. ');return;}if(state.modelBusy)return;const time=state.time;addReference(time);state.agentInput='';state.playing=false;await generateReport('match',time,'question',q);}
function filterEvents(filter,onlyPlayer=false,window=false){state.eventWindow=window;state.filter=filter;state.onlyPlayer=onlyPlayer;state.panel='events';state.panelPage=0;state.playing=false;render();}
document.addEventListener('focusin',e=>{if(!restoringFocus&&state.playing&&e.target.matches('input,select,textarea,button,summary,[data-player]')){state.playing=false;syncPlaybackControls();queueMicrotask(()=>render());}});
document.addEventListener('pointerdown',e=>{if(state.playing&&e.target.closest('button,input,select,summary,textarea,[role=button]')){stopped=!!e.target.closest('[data-action=play]');state.playing=false;syncPlaybackControls();}},true);
document.addEventListener('click',e=>{if(!data)return;const b=e.target.closest('[data-action]'),p=e.target.closest('[data-player]');if(p){stopped=false;selectPlayer(p.dataset.player);return;}if(!b){const lane=e.target.closest('.lane-track');if(lane){const rect=lane.getBoundingClientRect(),range=bounds();seek(range.start+clamp((e.clientX-rect.left)/rect.width,0,1)*range.size);}return;}const wasRunning=stopped;stopped=false;const action=b.dataset.action,id=b.dataset.id;
 if(action==='observation-mode'){state.observationMode=id;state.layers={...OBSERVATION_MODES[id].layers};state.showHistory=id==='movement';state.comparisonId=null;if(id==='movement')state.comboMode='potential';else if(id==='decision')state.comboMode='off';}
 else if(action==='sequence-time'){const anchor=state.reviewAnchor??sequence.end;state.panel='';state.screen='match';state.reviewAnchor=anchor;state.showHistory=true;seek(Number(b.dataset.time),null,true);return;}
 else if(action==='sequence-play'){const end=sequence.end,start=sequence.start;state.reviewAnchor=end;state.showHistory=true;state.panel='';state.screen='match';seek(start,null,true);state.clipEnd=end;state.speed=1;state.playing=true;rafLast=0;render();return;}
 else if(action==='sequence-follow'){const anchor=state.reviewAnchor;state.reviewAnchor=null;state.clipEnd=null;if(anchor!==null)seek(anchor,null,true);else render();return;}
 else if(action==='compare-option'){const option=decisions.find(r=>r.id===id&&r.available);if(option){state.comparisonId=id;state.showHistory=state.reviewAnchor!==null;state.route=option.receiver||null;state.observationMode='decision';state.layers={...OBSERVATION_MODES.decision.layers};state.comboMode='off';state.panel='';state.screen='match';state.playing=false;}}
 else if(action==='screen'){state.screen=id;}
 else if(action==='open-panel'){state.panel=id;state.panelPage=id==='events'?-1:0;state.playing=false;}
 else if(action==='close-panel'){state.panel='';}
 else if(action==='panel-page'){state.panelPage=Math.max(0,state.panelPage+Number(id));}
 else if(action==='report-page'){state.reportPage=Math.max(0,state.reportPage+Number(id));}
 else if(action==='roster-full'){state.panel='roster';state.panelPage=0;state.playing=false;}
 else if(action==='play'){state.clipEnd=null;state.reviewAnchor=null;feedRetryAt=0;state.playing=wasRunning?false:!state.playing;rafLast=0;}
 else if(action==='back'){seek(state.time-5);return;}
 else if(action==='retry-feed'){feedRetryAt=0;state.playing=true;}
 else if(action==='next'){seek(state.time+5);return;}
 else if(action==='player-event'){const ev=data.events.find(e=>e.id===id);if(ev)seek(Math.max(ev.time,ev.end||0),ev,true);return;}
 else if(action==='event'){state.panel='';state.screen='match';const ev=data.events.find(e=>e.id===id);if(ev)seek(Math.max(ev.time,ev.end||0),ev);return;}
 else if(action==='player-overview'){state.playerOpen=false;state.rosterExpanded=true;}
 else if(action==='roster-toggle'){state.panel='roster';state.panelPage=0;state.playing=false;}
 else if(action==='roster-sort'){state.rosterSort=id;}
 else if(action==='adjacent-player'){const ids=frame.players.map(p=>p.id),i=ids.indexOf(state.selected);selectPlayer(ids[(i+Number(id)+ids.length)%ids.length]);return;}
 else if(action==='inspect-defender'){selectPlayer(id);return;}
 else if(action==='combination'){state.playerOpen=true;state.rosterExpanded=false;state.comboMode='potential';state.comboId=id;state.comboStep=2;state.selected=spatial.combinations.find(c=>c.id===id)?.third.id||state.selected;state.playing=false;}
 else if(action==='combo-step'){state.comboStep=Number(id);state.playing=false;}
 else if(action==='sequence-event'){const ev=data.events.find(e=>e.id===id);if(ev){seek(Math.max(ev.time,ev.end||0),ev);return;}}
 else if(action==='last-decision'){const prior=previousDecision(data,state.time);if(prior){state.panel='';state.screen='match';seek(prior.time,null,true);return;}toast('Previous15s contained no confirmed carrier. ');}
 else if(action==='tactic-combo'){state.comboId=id;state.comboMode='potential';state.layers.passes=true;state.panel='';state.screen='match';}
 else if(action==='route'){state.comparisonId=null;state.panel='';state.screen='match';state.layers.passes=true;state.playerOpen=true;state.rosterExpanded=false;state.comboMode='off';state.route=id;state.selected=id;state.event=null;state.playing=false;}
 else if(action==='layer'){state.layers[id]=!state.layers[id];state.observationMode='custom';}
 else if(action==='focus-ball')state.focusBall=!state.focusBall;
 else if(action==='load-time'){seek(Number(b.dataset.time));state.filter='player';state.onlyPlayer=true;render();return;}
 else if(action==='lead-in'){seek(Number(b.dataset.time)-5);return;}
 else if(action==='reference'){state.playerOpen=true;addReference();generateReport();toast('Current time cited. ');}
 else if(action==='quote-event'){state.panel='agent';state.agentView='report';const ev=data.events.find(e=>e.id===id);if(ev){seek(Math.max(ev.time,ev.end||0),ev);addReference(state.time,ev);generateReport('match',state.time);} }
 else if(action==='brief-pre')generateReport('pre');
 else if(action==='assess-player'){generateReport();state.reportPage=0;}
 else if(action==='brief-now')generateReport();
 else if(action==='brief-post')generateReport('post');
 else if(action==='finish-report'){toast('Wait until full-time data is received for a complete review. ');}
 else if(action==='open-report'){state.panel='agent';state.agentView='report';state.reportPage=0;state.reportOpen=true;const r=state.reports.find(r=>r.id===id);state.activeReport=id;state.selected=r.selected;seek(r.time);return;}
 else if(action==='open-reference'){const r=state.references.find(r=>r.id===id);state.selected=r.selected;seek(r.time,data.events.find(e=>e.id===r.event));return;}
 else if(action==='metric'){filterEvents(id,true,true);return;}
 else if(action==='player-events'){filterEvents('player',true);return;}
 else if(action==='match-filter'){filterEvents(id,false);return;}
 else if(action==='events-prev')state.eventPage--;
 else if(action==='events-next')state.eventPage++;
 else if(action==='source'){state.panel='source';state.panelPage=0;state.playing=false;}
 else if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('This panel does not support full screen; Open the local page in a standalone browser. '));return;}
 else if(action==='check-model'){checkModel();return;}
 else if(action==='ask'){ask();return;}
 else if(action==='export'){const blob=new Blob([JSON.stringify({source:data.meta,kind:'real-match-references',references:state.references,reports:state.reports},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='next-touch-match-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
 render();});
document.addEventListener('pointerout',e=>{const point=e.target.closest('[data-chart-readout]');if(point&&!point.contains(e.relatedTarget)){const out=document.querySelector('.chart-readout'),selected=document.querySelector('.participation-point.active');if(out)out.textContent=selected?.dataset.chartReadout||'Hover for values · Select a player to link review';}});
document.addEventListener('pointerover',e=>{const point=e.target.closest('[data-chart-readout]');if(point){const out=document.querySelector('.chart-readout');if(out)out.textContent=point.dataset.chartReadout;}});
document.addEventListener('focusin',e=>{const point=e.target.closest('[data-chart-readout]');if(point){const out=document.querySelector('.chart-readout');if(out)out.textContent=point.dataset.chartReadout;}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.report-disclosure'))state.reportOpen=e.target.open;},true);
document.addEventListener('input',e=>{if(['agent-question','dock-question'].includes(e.target.id))state.agentInput=e.target.value;if(e.target.id==='time-seek'){state.playing=false;state.time=Number(e.target.value);state.event=null;state.clipEnd=null;state.reviewAnchor=null;pendingSlider=true;updateScene();}});
document.addEventListener('change',e=>{const id=e.target.id,value=e.target.value;if(id==='time-seek'){pendingSlider=false;render();return;}if(id==='combo-choice'){state.comboId=value;state.playing=false;}else if(id==='sequence-choice'){const ev=data.events.find(e=>e.id===value);if(ev)seek(Math.max(ev.time,ev.end||0),ev);return;}else if(id==='agent-view'){state.agentView=value;state.reportPage=0;}else if(id==='overview-metric'){if(['distance','high'].includes(state.rosterSort))state.rosterSort=value;state.overviewMetric=value;}else if(id==='combo-mode'){state.comboMode=value;state.playing=false;}else if(id==='speed')state.speed=Number(value);else if(id==='time-window')state.window=Number(value);else if(id==='player-picker'){selectPlayer(value);return;}else if(id==='event-filter'){state.filter=value;state.panelPage=0;}else if(id==='only-player'){state.onlyPlayer=e.target.checked;state.panelPage=0;}else if(id==='event-window'){state.eventWindow=e.target.checked;state.panelPage=0;}else if(id==='auto-agent'||id==='auto-dock'){state.auto=e.target.checked;if(state.auto)queueMicrotask(()=>maybeAuto('entry'));}else if(id==='local-model')state.model=value;else if(id==='role')state.role=value;else return;render();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='dock-question'){e.preventDefault();ask();return;}if(e.key==='Tab'&&state.panel){const panel=document.querySelector('.utility-panel'),nodes=[...panel.querySelectorAll('button:not([disabled]),input,select,textarea,a')].filter(n=>n.getClientRects().length);if(nodes.length&&((e.shiftKey&&document.activeElement===nodes[0])||(!e.shiftKey&&document.activeElement===nodes.at(-1)))){e.preventDefault();(e.shiftKey?nodes.at(-1):nodes[0]).focus();return;}}const p=e.target.closest('[data-player]');if(p&&['Enter',' '].includes(e.key)){e.preventDefault();selectPlayer(p.dataset.player);return;}if(e.key==='Escape'&&state.panel){state.panel='';render();return;}if(e.target.closest('input,textarea,select,button,summary,a')||state.panel)return;if(e.code==='Space'){e.preventDefault();state.clipEnd=null;state.reviewAnchor=null;state.playing=!state.playing;render();}if(e.key==='ArrowLeft')seek(state.time-5);if(e.key==='ArrowRight')seek(state.time+5);});
function updateTimelineLanes(){const fragment=document.createElement('div');fragment.innerHTML=timeline();for(const selector of ['.lane-scale','.event-lanes','.timeline-scale','.all-match-events'])document.querySelector(selector)?.replaceWith(fragment.querySelector(selector));}
function tick(now){const elapsed=rafLast?(now-rafLast)/1000:0;rafLast=now;
 if(data&&state.playing&&!pendingSlider){pumpFeed();const old=state.time;state.time=advanceReplay(state.time,elapsed,state.speed,data.frames.at(-1)[1],state.clipEnd??data.meta.end);
  if(now-paint>=160){paint=now;updateScene();if(Math.floor(old)!==Math.floor(state.time)||Math.floor(state.time)!==state.lastRenderedSecond){state.lastRenderedSecond=Math.floor(state.time);$('#insights').innerHTML=playerWorkspace();$('#match-review-mount').innerHTML=matchReview();$('#combination-mount').innerHTML=combinationPanel();updateTimelineLanes();assignFocusKeys();const trigger=receivedEvents().some(e=>Math.max(e.time,e.end||0)>(state.lastAgentEventTime||0)&&isDeadBall(e));state.lastAgentEventTime=state.time;maybeAuto(trigger?'dead-ball':'change');}}
  if(state.clipEnd!==null&&state.time>=state.clipEnd-.001){state.playing=false;state.clipEnd=null;render();}
  if(state.time>=data.meta.end-.001){state.time=data.meta.end;state.playing=false;generateReport('post',state.time,'full-time');render();}
 }requestAnimationFrame(tick);}
function matchReview(){const facts=matchFacts(data,state.time),p=frame.holder,event=selectedEvent()||frame.last;return `<div class="match-summary"><section class="summary-stats"><div class="section-head"><h2>Match stats</h2><span>As of ${clock(state.time)}</span></div><div class="match-stat-grid">${[['shots','Shot'],['onTarget','On target'],['passes','Pass'],['lost','Losses'],['corners','Corner'],['foulsReceived','Fouled'],['yellow','Yellow card'],['red','Red card']].map(([k,n])=>`<button data-action="match-filter" data-id="${({onTarget:'shots',corners:'restart',foulsReceived:'discipline'})[k]||k}" title="View ${n} events"><span>${n}</span><strong class="home-text">${facts.home[k]}</strong><i>:</i><strong class="away-text">${facts.away[k]}</strong></button>`).join('')}</div></section><section class="summary-options"><div class="section-head"><h3>Passing options</h3>${button('Compare choices','open-panel','data-id="tactics"')}</div><p class="summary-holder">${p?`${teamName(p.team)} ${p.number} · Estimated carrier`:'Carrier unconfirmed'}${analysis.nearest?' · Opponent '+analysis.nearest.distance.toFixed(1)+'m':''}</p>${analysis.options.slice(0,3).map(o=>`<button data-action="route" data-id="${o.id}" aria-pressed="${state.route===o.id}"><strong>${o.player.number}</strong><span>${o.distance.toFixed(0)}m · ${o.offside?'Offside risk':o.margin>=0?'Ball first':'Opponent first'}</span><b class="${o.margin<0?'risk':''}">${o.margin.toFixed(1)}s</b></button>`).join('')||`<p class="empty">${decisionReason(frame)}</p>${button('Last carrier','last-decision')}`}</section><section class="summary-runs"><div class="section-head"><h3>${frame.ball?'Off-ball runs':'Movement'}</h3><span>Projection 2s</span></div>${analysis.runs.slice(0,3).map(r=>`<button data-player="${r.player.id}" aria-pressed="${state.selected===r.player.id}"><strong>${r.player.number}</strong><span>${r.label}</span><b>${(r.player.speed*3.6).toFixed(1)}<small> km/h</small></b></button>`).join('')||'<p class="empty">No clear movement</p>'}</section>${event?`<section class="summary-event"><div class="section-head"><h3>${selectedEvent()?'Selected event':'Latest event'}</h3><time>${clock(event.time)}</time></div><p>${eventName(event)}</p><small>${teamName(event.team)} ${shirt(event.from)||'—'}${event.to?' → '+shirt(event.to):''}</small><div>${button('Review','lead-in',`data-time="${event.time}"`)}${button('Cite','quote-event',`data-id="${event.id}"`)}</div></section>`:''}<div class="summary-actions">${button('Compare choices','open-panel','data-id="tactics"')}${button('Event evidence','open-panel','data-id="events"')}${button('Match report','open-panel','data-id="match-report"')}</div></div>`;}
function playerColumn(){const p=data.meta.roster.find(p=>p.id===state.selected),m=playerMetrics(data,p.id,state.time),old=playerMetrics(data,p.id,Math.max(0,state.time-300)),trend=loadTrend(data,p.id,state.time),max=Math.max(120,...trend.map(v=>v.distance));return `<section class="compact-player"><div class="compact-player-head">${avatar(p)}<div><h3>${playerLabel(p)}</h3><span>Last 5′ ${m.active<180?'· Under 3′ tracked':''}</span></div>${button('Player events','player-events')}</div><div class="compact-metrics">${[['Touches',m.touches,'player'],['Pass',m.passes,'passes'],['Losses',m.lost,'lost'],['Duels',m.won+'/'+m.duels,'ground']].map(([n,v,k])=>valueButton(v,n,k)).join('')}</div><div class="compact-load"><div class="section-head"><h3>Movement trend</h3><span>Last 10′ · m /  min</span></div><div class="load-chart">${trend.map(v=>`<button data-action="load-time" data-time="${v.time}" aria-label="Review${clock(v.time)}Distance${Math.round(v.distance)}m" title="${clock(v.time)} Distance${Math.round(v.distance)}m / High speed${Math.round(v.high)}m"><span style="height:${Math.max(2,v.distance/max*42)}px"><i style="height:${v.distance?v.high/v.distance*100:0}%"></i></span><small>${v.partial?'Current':Math.floor(v.time/60)+'′'}</small></button>`).join('')}</div></div><div class="compact-load-values">${[['distance','Distance','m'],['high','High speed','m'],['sprints','Sprint',' times'],['accels','Acceleration',' times']].map(([k,n,u])=>`<div><span>${n}</span><strong>${Math.round(m[k])}${u}</strong><small>Previous 5′ ${state.time>=600?Math.round(old[k])+u:'—'}</small></div>`).join('')}</div>${playerEventTracks()}<div class="compact-spatial">${playerProjection(p)}</div></section>`;}
function agentColumn(){const report=state.reports.filter(r=>r.time<=state.time&&r.phase==='match'&&(!state.playerOpen||r.selected===state.selected)).at(-1),modelText=report&&report.provider!=='rules'?report.advice.replace(/\*\*/g,''):'';return `<section class="agent-dock-content"><div class="agent-dock-head"><strong>Agent</strong><span role="status">${state.modelBusy?esc(state.modelLabel)+' Analysing '+shirt(state.modelTarget)+' in progress':state.model?esc(state.modelLabel):'Evidence rules'}</span><label><input type="checkbox" id="auto-dock" ${state.auto?'checked':''}>Proactive</label>${button('Details / Ask','open-panel','data-id="agent"')}</div><div class="agent-live"><time>${clock(state.time)}</time><p>${esc(tactical.notice)}</p></div><button class="agent-model-note" ${report?`data-action="open-report" data-id="${report.id}"`:'data-action="open-panel" data-id="agent"'}>${report?.pending?'Generating tactical feedback for this moment…':report?.error?esc(report.error)+' · Rule-based observations retained':report?.reviewWarnings?.length?esc(report.reviewWarnings.join(' ')):modelText?`Read feedback · ${clock(report.time)} · ${esc(modelText)}`:state.auto?'Live evidence rules are active; The model adds feedback on entry, state changes and dead balls. ':'Proactive analysis is paused, You can still ask a question. '}</button><div class="agent-dock-composer"><input id="dock-question" value="${esc(state.agentInput)}" aria-label="Ask the agent" placeholder="Cite ${clock(state.time)}, ask a question…">${button('Send','ask',state.modelBusy?'disabled':'','primary')}</div></section>`;}
function maybeAuto(trigger='change'){
 if(!data||state.panel||state.modelState==='checking'||state.autoCount>=12)return;
 if(!shouldAutoAnalyze({enabled:state.auto,busy:state.modelBusy,now:Date.now(),lastWall:state.lastAutoWall,key:tactical.key,lastKey:state.lastAutoKey,trigger}))return;
 state.lastAutoWall=Date.now();state.lastAutoKey=tactical.key;state.autoCount++;
 generateReport('match',state.time,trigger,'Review current pressure around the ball, box density and wide/crossing candidates. Give up to three concise recommendations, Separate geometry estimates from facts, Do not present negative-margin routes as safe. ');
}
function panelPager(page,total,action='panel-page'){return `<div class="panel-pager">${button('Previous',action,`data-id="-1" ${page<=0?'disabled':''}`)}<span>${page+1} / ${Math.max(1,total)}</span>${button('Next',action,`data-id="1" ${page+1>=total?'disabled':''}`)}</div>`;}
function utilityPanel(){if(!state.panel)return '';const type=state.panel,title={events:'Event evidence',source:'Definitions',tactics:'Decision comparison',routes:'Passes & combinations',sequence:'Tactical sequence · Last10s',quality:'Data quality & limits',tracking:'Out-of-bounds evidence',agent:'Player Agent',roster:'Switch player','match-report':'Match report'}[type]||'Detailed data',size=Math.max(3,Math.min(12,Math.floor((window.innerHeight-215)/(window.innerWidth<700?65:43))));let content='';
 if(type==='events'){let list=receivedEvents().filter(filterMatch);if(state.onlyPlayer)list=list.filter(e=>e.from===state.selected||e.to===state.selected);if(state.eventWindow)list=list.filter(e=>e.time>state.time-300&&Math.max(e.time,e.end||0)<=state.time);const pages=Math.max(1,Math.ceil(list.length/size));if(state.panelPage<0)state.panelPage=Math.max(0,Math.floor(list.findIndex(e=>e.time>=state.time)/size));state.panelPage=clamp(state.panelPage,0,pages-1);content=`<div class="panel-filters"><label>Events<select id="event-filter">${[['all','All'],['passes','Pass'],['lost','Losses'],['ground','Ground duel'],['shots','Shot'],['restart','Set piece'],['discipline','Foul / Discipline'],['yellow','Yellow card'],['red','Red card'],['player','Selected player']].map(([v,n])=>`<option value="${v}" ${state.filter===v?'selected':''}>${n}</option>`).join('')}</select></label><label><input type="checkbox" id="only-player" ${state.onlyPlayer?'checked':''}>Selected player</label><label><input type="checkbox" id="event-window" ${state.eventWindow?'checked':''}>Last 5′</label><span>${list.length} events</span></div><div class="utility-events">${list.slice(state.panelPage*size,(state.panelPage+1)*size).map(e=>`<div class="utility-event"><time>${clock(e.time)}</time><span><i class="team-dot ${e.team}"></i>${teamName(e.team)} ${shirt(e.from)||'—'}</span><strong>${eventName(e)}</strong><span class="event-recipient">${e.to?'→ '+shirt(e.to):''}</span><div>${button('Seek','event',`data-id="${e.id}"`)}${button('Cite','quote-event',`data-id="${e.id}"`)}</div></div>`).join('')||'<p class="empty">No events match this filter</p>'}</div>${panelPager(state.panelPage,pages)}`;}
 else if(type==='tactics'){content=`<div class="comparison-context"><strong>${strategies.phase}</strong><time>${clock(state.time)}</time></div>${comparisonView(decisions,state.comparisonId)}<div class="comparison-actions">${button('All passes / Two-pass links','open-panel','data-id="routes"')}${button('Review 10s sequence','open-panel','data-id="sequence"')}${button('Data quality','open-panel','data-id="quality"')}</div>`;}
 else if(type==='quality'){content=qualityView(quality);}
 else if(type==='sequence'){const count=window.innerHeight<900?3:6,pages=Math.max(1,Math.ceil(sequence.records.length/count));state.panelPage=clamp(state.panelPage,0,pages-1);content=processView(sequence,state.reviewAnchor!==null,state.panelPage,count)+panelPager(state.panelPage,pages);}
 else if(type==='routes'){const rows=[...analysis.options.map(o=>`<button data-action="route" data-id="${o.id}"><strong>Pass to ${teamName(o.player.team)} ${o.player.number}</strong><span>${o.distance.toFixed(1)}m · Gain ${o.progress.toFixed(1)}m · Interception margin ${o.margin.toFixed(1)}s${o.offside?' · Offside risk':''}</span></button>`),...spatial.combinations.map(c=>`<button data-action="tactic-combo" data-id="${c.id}"><strong>Two passes ${c.holder.number} → ${c.first.player.number} → ${c.third.number}</strong><span>Gain ${c.progress.toFixed(1)}m · Minimum margin ${c.margin.toFixed(1)}s</span></button>`)];const count=Math.max(2,Math.min(8,Math.floor((window.innerHeight-430)/65))),pages=Math.max(1,Math.ceil(rows.length/count));state.panelPage=clamp(state.panelPage,0,pages-1);content=`<div class="strategy-options"><strong>${strategies.phase} · ${strategies.reason}</strong>${strategies.choices.map(c=>c.option?button(`${c.label} → ${c.option.player.number} · Gain ${c.option.progress.toFixed(0)}m · Margin ${c.option.margin.toFixed(1)}s${c.option.margin<=0?' · Interception risk':''}`,'route',`data-id="${c.option.id}"`):`<span>${c.label} · ${c.reason}</span>`).join('')}</div><p>${clock(state.time)} · ${decisionReason(frame)} · ${analysis.options.length} receivers / ${spatial.combinations.length} combinations</p><p>Uses current positions, past velocity and a shared arrival model. Margin is opponent arrival minus ball arrival; Not success probability or declared tactics. </p><div class="tactics-list">${rows.slice(state.panelPage*count,(state.panelPage+1)*count).join('')||button('Last carrier','last-decision')}</div>${panelPager(state.panelPage,pages)}`;}
 else if(type==='tracking'){const rows=frame.players.filter(outsidePitch),count=Math.max(2,Math.min(8,Math.floor((window.innerHeight-270)/65))),pages=Math.max(1,Math.ceil(rows.length/count));state.panelPage=clamp(state.panelPage,0,pages-1);content=`<p>${clock(frame.sourceTime)} · Source frame ${data.frames[frame.index][0]}</p><p>Pitch boundary 105 × 68m. Coordinates below come directly from the source; They may reflect a boundary crossing or tracking error, Available evidence cannot distinguish them. Source coordinates are retained, Shown with a dashed outline, Excluded from in-pitch receiving candidates. </p><div class="tactics-list">${rows.slice(state.panelPage*count,(state.panelPage+1)*count).map(p=>`<button data-player="${p.id}"><strong>${playerLabel(p)} · Outside ${outsideDistance(p).toFixed(2)}m</strong><span>x ${p.x.toFixed(3)}m / y ${p.y.toFixed(3)}m</span></button>`).join('')||'No out-of-bounds coordinates in this frame. '}</div>${panelPager(state.panelPage,pages)}`;}
 else if(type==='source'){const wrapper=document.createElement('div');wrapper.innerHTML=coverage();const definitions=[...wrapper.querySelectorAll('.metric-definitions dl>div')].map(e=>({title:e.querySelector('dt').textContent,body:e.querySelector('dd').textContent})),items=[...definitions,...catalog.map(([group,name,status,note])=>({title:group+' · '+name,body:({observed:'Source observations',derived:'Computed locally',predicted:'Model estimate',missing:'Unavailable'}[status]||status)+' · '+note}))],count=window.innerWidth<700?2:3,pages=Math.ceil(items.length/count);state.panelPage=clamp(state.panelPage,0,pages-1);content=`<div class="source-pages">${items.slice(state.panelPage*count,(state.panelPage+1)*count).map(v=>`<section><h3>${esc(v.title)}</h3><p>${esc(v.body)}</p></section>`).join('')}</div>${panelPager(state.panelPage,pages)}<div class="source-credit">Seeded behaviour simulation · 5 Hz · Fictional players<br><a href="/data/synthetic/manifest.json" target="_blank" rel="noreferrer">Data manifest</a> · <a href="/coach-validation.html">Scenario validation</a></div>`;}
 else if(type==='roster'){const rows=squadEvidence(),count=Math.max(3,Math.min(11,Math.floor((window.innerHeight-200)/45))),pages=Math.max(1,Math.ceil(Math.max(...['home','away'].map(t=>data.meta.roster.filter(p=>p.team===t).length))/count));state.panelPage=clamp(state.panelPage,0,pages-1);content=`<div class="utility-rosters">${['home','away'].map(t=>`<section><h3>${teamName(t)}</h3>${data.meta.roster.filter(p=>p.team===t).slice(state.panelPage*count,(state.panelPage+1)*count).map(p=>`<button data-player="${p.id}">${avatar(p)}<strong>${p.number}</strong><span>${rows.some(r=>r.p.id===p.id)?'currently tracked':'No tracking'}</span></button>`).join('')}</section>`).join('')}</div>${panelPager(state.panelPage,pages)}`;}
 else if(type==='agent'||type==='match-report'){const reports=state.reports.filter(r=>r.time<=state.time).filter(r=>type==='agent'?r.selected===state.selected&&r.phase==='match':r.phase!=='match'),report=reports.find(r=>r.id===state.activeReport)||reports.at(-1);content=type==='agent'?`<div class="panel-filters"><strong>${playerLabel(data.meta.roster.find(p=>p.id===state.selected))}</strong><select id="agent-view" aria-label="Agent Content">${[['report','Review & ask'],['history','Reference history'],['model','Model connection']].map(([v,n])=>`<option value="${v}" ${state.agentView===v?'selected':''}>${n}</option>`).join('')}</select><label><input type="checkbox" id="auto-agent" ${state.auto?'checked':''}>Proactive analysis</label></div>`:`<div class="panel-filters">${button('Pre-match check','brief-pre')}${button('Post-match review','brief-post')}</div>`;
 if(type==='agent'&&state.agentView==='model'){content+=`<section class="model-panel"><h3>${esc(state.modelLabel)}</h3><p>${state.modelState==='ready'?'Available model '+state.models.length:state.modelState==='checking'?'Checking connection':'Not configured · Using evidence rules'}</p><label>Model<select id="local-model"><option value="">Evidence rules</option>${state.models.map(m=>`<option value="${esc(m)}" ${state.model===m?'selected':''}>${'Agent'}</option>`).join('')}</select></label>${button('Check connection','check-model')}<p>${state.modelProvider==='ollama'?'Calls local models only Ollama. ':'Called through the local server '+esc(state.modelLabel)+'; Sends the currently cited synthetic match evidence. '}</p><p>${esc(state.modelError)}</p></section>`;}
 else if(type==='agent'&&state.agentView==='history'){const count=Math.max(3,Math.min(8,size)),items=[...reports].reverse(),pages=Math.max(1,Math.ceil(items.length/count));state.panelPage=clamp(state.panelPage,0,pages-1);content+=`<div class="report-history">${items.slice(state.panelPage*count,(state.panelPage+1)*count).map(r=>button(`${clock(r.time)} · ${r.title}`,'open-report',`data-id="${r.id}"`)).join('')||'<p>No reports for this player</p>'}</div>${panelPager(state.panelPage,pages)}${button('Export references & reports','export')}`;}
 else{const text=report?[report.pending?state.modelLabel+' Generating…':report.summary,report.advice,report.limits].join('\n\n').replace(/\*\*/g,''):'No review yet. Choose Review to analyse this moment. ',limit=Math.max(160,Math.min(700,Math.floor((window.innerHeight-385)/24)*Math.floor(Math.min(window.innerWidth-60,760)/14))),pages=Math.max(1,Math.ceil(text.length/limit));state.reportPage=clamp(state.reportPage,0,pages-1);content+=`<article class="paged-report"><div class="section-head"><h3>${esc(report?.title||'Current player')}</h3><time>${clock(report?.time||state.time)}</time></div><p>${esc(text.slice(state.reportPage*limit,(state.reportPage+1)*limit))}</p></article>${panelPager(state.reportPage,pages,'report-page')}<div class="panel-evidence">${(report?.evidence||[]).slice(0,3).map(id=>{const e=data.events.find(e=>e.id===id);return e?button(`${clock(e.time)} ${typeName[e.type]}`,'event',`data-id="${id}"`):'';}).join('')}</div>${type==='agent'?`<div class="panel-composer"><label for="agent-question">Cite ${clock(state.time)} · ${data.meta.roster.find(p=>p.id===state.selected)?.name}</label><textarea id="agent-question" rows="2" placeholder="Ask about this player and moment…">${esc(state.agentInput)}</textarea><div>${button('Review now','assess-player')}${button('Ask','ask',state.modelBusy?'disabled':'','primary')}</div></div>`:report?.phase==='post'&&report.time<data.meta.end-.25?button('Available at full time','finish-report','disabled'):''}`;}}
 return `<section class="utility-panel" role="dialog" aria-modal="true" aria-label="${title}"><header><h2>${title}</h2>${button(icon('close')+'Back to desk','close-panel')}</header><div class="utility-content">${content}</div></section>`;}

async function boot(){try{const meta=await fetch('/api/replay/meta').then(r=>{if(!r.ok)throw Error('manifest');return r.json();});$('#app .boot p').textContent='Connecting to match stream…';data=prepareData(meta);state.time=meta.start;await pumpFeed(true);refresh();state.selected=frame.holder?.id||'Player6';addBrief('pre');state.reportOpen=false;render();checkModel();requestAnimationFrame(tick);}catch(e){$('#app').innerHTML=`<div class="boot error"><h1>Match stream disconnected</h1><p>${esc(e.message)}</p><a href="/">Reconnect</a></div>`;}}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(data)render();},120);});
boot();
